const config = $('CONFIG - Preencher aqui1').first().json;
const targetAccountId = String(config.target_account_id || '').trim();
const targetSellerId = String(config.target_seller_id || '').trim();

const workflowName = config.seller_workflow_name || 'ml_dashboards_mvp1_seller_sync';
const schema = config.schema || 'ml_dashboards';
const timeZone = config.time_zone || 'America/Sao_Paulo';

const requiredConfig = [
  ['ml_client_id', config.ml_client_id],
  ['ml_client_secret', config.ml_client_secret],
  ['supabase_url', config.supabase_url],
  ['supabase_service_role_key', config.supabase_service_role_key],
];

const missingConfig = requiredConfig
  .filter(([name, value]) => !value || String(value).startsWith('PREENCHA_') || String(value).includes('SEU_PROJETO'))
  .map(([name]) => name);

if (missingConfig.length) {
  throw new Error(`Preencha estes campos no node CONFIG - Preencher aqui: ${missingConfig.join(', ')}`);
}

const supabaseUrl = config.supabase_url.replace(/\/+$/, '');
const serviceRoleKey = config.supabase_service_role_key;
const mlClientId = config.ml_client_id;
const mlClientSecret = config.ml_client_secret;
const helpers = this.helpers;

function nowIso() {
  return new Date().toISOString();
}

function todayInTimeZone() {
  return new Intl.DateTimeFormat('en-CA', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(new Date());
}

function firstRow(response) {
  if (Array.isArray(response)) return response[0] || null;
  return response || null;
}

function compactError(error) {
  const responseBody = error?.response?.body ?? error?.response?.data ?? error?.body ?? error?.data ?? null;
  return {
    name: error?.name || null,
    message: error?.message || String(error),
    statusCode: error?.statusCode || error?.response?.statusCode || error?.response?.status || error?.status || null,
    url: error?.config?.url || error?.options?.url || null,
    body: typeof responseBody === 'string' ? responseBody.slice(0, 3000) : responseBody,
  };
}

async function request(options) {
  return await helpers.httpRequest({
    timeout: 120000,
    json: true,
    ...options,
  });
}

async function supabaseRequest(method, path, body = undefined, prefer = undefined) {
  const headers = {
    apikey: serviceRoleKey,
    Authorization: `Bearer ${serviceRoleKey}`,
    Accept: 'application/json',
    'Content-Type': 'application/json',
    'Accept-Profile': schema,
  };

  if (method !== 'GET') {
    headers['Content-Profile'] = schema;
  }

  if (prefer) {
    headers.Prefer = prefer;
  }

  const options = {
    method,
    url: `${supabaseUrl}/rest/v1${path}`,
    headers,
  };

  if (body !== undefined) {
    options.body = body;
  }

  return await request(options);
}

async function createSyncRun(accountId) {
  const response = await supabaseRequest(
    'POST',
    '/sync_runs',
    {
      account_id: accountId,
      workflow_name: workflowName,
      status: 'running',
      started_at: nowIso(),
    },
    'return=representation'
  );

  return firstRow(response)?.id || null;
}

async function finishSyncRun(runId, accountId, status, error = null) {
  const payload = {
    status,
    finished_at: nowIso(),
  };

  if (error) {
    const errorPayload = compactError(error);
    payload.error_message = errorPayload.message;
    payload.raw_error = errorPayload;
  }

  if (runId) {
    return await supabaseRequest(
      'PATCH',
      `/sync_runs?id=eq.${encodeURIComponent(runId)}`,
      payload,
      'return=representation'
    );
  }

  return await supabaseRequest(
    'POST',
    '/sync_runs',
    {
      account_id: accountId,
      workflow_name: workflowName,
      status,
      started_at: payload.finished_at,
      ...payload,
    },
    'return=representation'
  );
}

function formEncode(payload) {
  return Object.entries(payload)
    .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`)
    .join('&');
}

async function refreshMercadoLivreToken(refreshToken) {
  const body = formEncode({
    grant_type: 'refresh_token',
    client_id: mlClientId,
    client_secret: mlClientSecret,
    refresh_token: refreshToken,
  });

  return await request({
    method: 'POST',
    url: 'https://api.mercadolibre.com/oauth/token',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
      Accept: 'application/json',
    },
    body,
  });
}

async function getMercadoLivreSeller(accessToken) {
  return await request({
    method: 'GET',
    url: 'https://api.mercadolibre.com/users/me',
    headers: {
      Authorization: `Bearer ${accessToken}`,
      Accept: 'application/json',
    },
  });
}

function normalizeSeller(account, seller) {
  const rep = seller.seller_reputation || {};
  const tx = rep.transactions || {};
  const ratings = tx.ratings || {};
  const metrics = rep.metrics || {};

  return {
    account_id: account.account_id,
    seller_id: seller.id,
    nickname: seller.nickname || null,
    email: seller.email || null,
    first_name: seller.first_name || null,
    last_name: seller.last_name || null,
    registration_date: seller.registration_date || null,
    country_id: seller.country_id || null,
    site_id: seller.site_id || null,
    user_type: seller.user_type || null,
    permalink: seller.permalink || null,
    points: seller.points ?? null,
    tags: seller.tags || [],
    seller_experience: seller.seller_experience || null,
    status: seller.status || {},
    reputation_level_id: rep.level_id || null,
    power_seller_status: rep.power_seller_status || null,
    reputation_real_level: rep.real_level || null,
    protection_end_date: rep.protection_end_date || null,
    transactions_period: tx.period || null,
    transactions_total: tx.total ?? null,
    transactions_completed: tx.completed ?? null,
    transactions_canceled: tx.canceled ?? null,
    rating_positive: ratings.positive ?? null,
    rating_neutral: ratings.neutral ?? null,
    rating_negative: ratings.negative ?? null,
    sales_completed: metrics.sales?.completed ?? null,
    claims_rate: metrics.claims?.rate ?? null,
    claims_value: metrics.claims?.value ?? null,
    delayed_handling_time_rate: metrics.delayed_handling_time?.rate ?? null,
    delayed_handling_time_value: metrics.delayed_handling_time?.value ?? null,
    cancellations_rate: metrics.cancellations?.rate ?? null,
    cancellations_value: metrics.cancellations?.value ?? null,
    raw: seller,
    synced_at: nowIso(),
  };
}

function buildSnapshot(currentSeller) {
  return {
    account_id: currentSeller.account_id,
    seller_id: currentSeller.seller_id,
    snapshot_date: todayInTimeZone(),
    reputation_level_id: currentSeller.reputation_level_id,
    power_seller_status: currentSeller.power_seller_status,
    transactions_total: currentSeller.transactions_total,
    transactions_completed: currentSeller.transactions_completed,
    transactions_canceled: currentSeller.transactions_canceled,
    rating_positive: currentSeller.rating_positive,
    rating_neutral: currentSeller.rating_neutral,
    rating_negative: currentSeller.rating_negative,
    sales_completed: currentSeller.sales_completed,
    claims_rate: currentSeller.claims_rate,
    claims_value: currentSeller.claims_value,
    delayed_handling_time_rate: currentSeller.delayed_handling_time_rate,
    delayed_handling_time_value: currentSeller.delayed_handling_time_value,
    cancellations_rate: currentSeller.cancellations_rate,
    cancellations_value: currentSeller.cancellations_value,
    raw: currentSeller.raw,
    synced_at: currentSeller.synced_at,
  };
}

const accountsResponse = await supabaseRequest(
  'GET',
  '/oauth_tokens?select=account_id,refresh_token,access_token,expires_at,ml_user_id,accounts!inner(account_name,active)&accounts.active=eq.true'
);

let accounts = Array.isArray(accountsResponse) ? accountsResponse : [accountsResponse].filter(Boolean);

if (targetAccountId) {
  accounts = accounts.filter((account) => String(account.account_id) === targetAccountId);
}

if (targetSellerId) {
  accounts = accounts.filter((account) => String(account.ml_user_id || '') === targetSellerId);
}
const results = [];

if (!accounts.length) {
  return [
    {
      json: {
        status: 'success',
        message: 'Nenhuma conta ativa com refresh_token encontrada.',
        processed: 0,
      },
    },
  ];
}

for (const account of accounts) {
  let runId = null;
  const accountId = account.account_id;
  const accountName = account.accounts?.account_name || null;

  try {
    if (!accountId) throw new Error('Linha de oauth_tokens sem account_id.');
    if (!account.refresh_token) throw new Error(`Conta ${accountId} sem refresh_token.`);

    runId = await createSyncRun(accountId);

    let accessToken = account.access_token || null;
    let sellerId = account.ml_user_id || null;
    const expiresAtTime = account.expires_at ? new Date(account.expires_at).getTime() : 0;
    const hasValidAccessToken = accessToken && expiresAtTime > Date.now() + 5 * 60 * 1000;

    if (!hasValidAccessToken) {
      const token = await refreshMercadoLivreToken(account.refresh_token);
      if (!token?.access_token) {
        throw new Error('Mercado Livre nao retornou access_token ao renovar OAuth.');
      }

      const expiresAt = token.expires_in
        ? new Date(Date.now() + Math.max(token.expires_in - 300, 0) * 1000).toISOString()
        : null;

      const tokenPayload = {
        account_id: accountId,
        ml_user_id: token.user_id ?? account.ml_user_id ?? null,
        access_token: token.access_token,
        refresh_token: token.refresh_token || account.refresh_token,
        token_type: token.token_type || 'Bearer',
        expires_in: token.expires_in ?? null,
        scope: token.scope ?? null,
        expires_at: expiresAt,
        updated_at: nowIso(),
      };

      await supabaseRequest(
        'POST',
        '/oauth_tokens?on_conflict=account_id',
        tokenPayload,
        'resolution=merge-duplicates,return=representation'
      );

      accessToken = token.access_token;
      sellerId = token.user_id ?? sellerId;
    }

    if (!accessToken) {
      throw new Error('Access token ausente. Rode o MVP1 com refresh_token valido para gerar um access_token.');
    }

    const seller = await getMercadoLivreSeller(accessToken);
    const currentSeller = normalizeSeller(account, seller);

    await supabaseRequest(
      'POST',
      '/sellers_current?on_conflict=seller_id',
      currentSeller,
      'resolution=merge-duplicates,return=representation'
    );

    await supabaseRequest(
      'POST',
      '/seller_daily_snapshots?on_conflict=account_id,snapshot_date',
      buildSnapshot(currentSeller),
      'resolution=merge-duplicates,return=representation'
    );

    await supabaseRequest(
      'PATCH',
      `/accounts?id=eq.${encodeURIComponent(accountId)}`,
      {
        ml_user_id: currentSeller.seller_id,
        nickname: currentSeller.nickname,
        site_id: currentSeller.site_id,
        last_sync_at: currentSeller.synced_at,
        updated_at: currentSeller.synced_at,
      },
      'return=representation'
    );

    await finishSyncRun(runId, accountId, 'success');

    results.push({
      json: {
        status: 'success',
        account_id: accountId,
        account_name: accountName,
        seller_id: currentSeller.seller_id,
        nickname: currentSeller.nickname,
        snapshot_date: todayInTimeZone(),
        sync_run_id: runId,
      },
    });
  } catch (error) {
    try {
      await finishSyncRun(runId, accountId, 'error', error);
    } catch (logError) {
      results.push({
        json: {
          status: 'error',
          account_id: accountId || null,
          account_name: accountName,
          error: compactError(error),
          log_error: compactError(logError),
        },
      });
      continue;
    }

    results.push({
      json: {
        status: 'error',
        account_id: accountId || null,
        account_name: accountName,
        error: compactError(error),
        sync_run_id: runId,
      },
    });
  }
}

return results;

