const ordersDaysBack = Math.min(Math.max(Number(config.orders_days_back || 30), 1), 365);
const ordersChunkDays = Math.min(Math.max(Number(config.orders_chunk_days || 7), 1), 31);
const orderPageLimit = Math.min(Math.max(Number(config.order_page_limit || 50), 1), 50);
const maxOrdersPerAccount = Math.max(Number(config.max_orders_per_account || 2000), 1);
const supabaseUpsertBatchSize = Math.max(Number(config.supabase_upsert_batch_size || 100), 1);
const syncDailySummary = config.sync_daily_summary !== false;

const requiredConfig = [
