const serviceRoleKey = config.supabase_service_role_key;
const mlClientId = config.ml_client_id;
const mlClientSecret = config.ml_client_secret;
const helpers = this.helpers;

function nowIso() {
  return new Date().toISOString();
}

function todayInTimeZone() {
  return new Intl.DateTimeFormat('en-CA', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(new Date());
}

function firstRow(response) {
  if (Array.isArray(response)) return response[0] || null;
  return response || null;
}

function compactError(error) {
  const responseBody = error?.response?.body ?? error?.response?.data ?? error?.body ?? error?.data ?? null;
  return {
    name: error?.name || null,
    message: error?.message || String(error),
    statusCode: error?.statusCode || error?.response?.statusCode || error?.response?.status || error?.status || null,
    url: error?.config?.url || error?.options?.url || null,
    body: typeof responseBody === 'string' ? responseBody.slice(0, 3000) : responseBody,
  };
}

function chunkArray(values, size) {
  const chunks = [];
  for (let index = 0; index < values.length; index += size) {
    chunks.push(values.slice(index, index + size));
  }
  return chunks;
}

function buildQuery(params) {
  return Object.entries(params)
    .filter(([, value]) => value !== undefined && value !== null && value !== '')
    .map(([key, value]) => encodeURIComponent(key) + '=' + encodeURIComponent(value))
    .join('&');
}

function formEncode(payload) {
  return Object.entries(payload)
    .map(([key, value]) => encodeURIComponent(key) + '=' + encodeURIComponent(value))
    .join('&');
}

function normalizeNumber(value) {
  if (value === null || value === undefined || value === '') return null;
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}

function normalizeInteger(value) {
  const number = normalizeNumber(value);
  return number === null ? null : Math.trunc(number);
}

function normalizeDate(value) {
  if (!value) return null;
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? null : date.toISOString();
}

function dateOnlyInTimeZone(value) {
  const date = value ? new Date(value) : new Date();
  if (Number.isNaN(date.getTime())) return todayInTimeZone();

  return new Intl.DateTimeFormat('en-CA', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(date);
}

