function normalizeWindowDate(value, boundary) {
  if (!value) return '';

  if (/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    const time = boundary === 'to' ? '23:59:59.000' : '00:00:00.000';
    return value + 'T' + time + '-03:00';
  }

  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new Error('Data invalida em orders_date_' + boundary + ': ' + value);
  }

  return value;
}

function buildOrdersWindow() {
  if (ordersDateFrom || ordersDateTo) {
    if (!ordersDateFrom || !ordersDateTo) {
      throw new Error('Preencha orders_date_from e orders_date_to juntos, ou deixe ambos vazios para usar orders_days_back.');
    }

    return {
      from: normalizeWindowDate(ordersDateFrom, 'from'),
      to: normalizeWindowDate(ordersDateTo, 'to'),
      mode: 'fixed_date_window',
    };
  }

  const to = new Date();
  const from = new Date(to.getTime() - ordersDaysBack * 24 * 60 * 60 * 1000);

  return {
    from: from.toISOString(),
    to: to.toISOString(),
    mode: 'relative_days_back',
  };
}

function buildOrderWindowChunks() {
  const mainWindow = buildOrdersWindow();
  const fromDate = new Date(mainWindow.from);
  const toDate = new Date(mainWindow.to);

  if (Number.isNaN(fromDate.getTime()) || Number.isNaN(toDate.getTime())) {
    throw new Error('Janela de pedidos invalida: ' + JSON.stringify(mainWindow));
  }

  if (fromDate > toDate) {
    throw new Error('orders_date_from nao pode ser maior que orders_date_to.');
  }

  const chunks = [];
  const chunkMs = ordersChunkDays * 24 * 60 * 60 * 1000;
  let cursor = fromDate;

  while (cursor <= toDate) {
    const chunkFrom = new Date(cursor);
    const chunkTo = new Date(Math.min(cursor.getTime() + chunkMs - 1, toDate.getTime()));

    chunks.push({
      from: chunkFrom.toISOString(),
      to: chunkTo.toISOString(),
      mode: mainWindow.mode,
    });

    cursor = new Date(chunkTo.getTime() + 1);
  }

  return chunks;
}

async function fetchOrders(accessToken, sellerId) {
  const ordersById = new Map();
  const chunks = buildOrderWindowChunks();

  for (const window of chunks) {
    let offset = 0;
    let total = null;

    while (ordersById.size < maxOrdersPerAccount) {
      if (offset >= 10000) {
        throw new Error('A janela ' + window.from + ' ate ' + window.to + ' ultrapassou o limite de offset 10000 da API do Mercado Livre. Reduza orders_chunk_days no CONFIG.');
      }

      const query = buildQuery({
        seller: sellerId,
        'order.date_created.from': window.from,
        'order.date_created.to': window.to,
        sort: 'date_desc',
        limit: orderPageLimit,
        offset,
      });

      const response = await request({
        method: 'GET',
        url: 'https://api.mercadolibre.com/orders/search?' + query,
        headers: {
          Authorization: 'Bearer ' + accessToken,
          Accept: 'application/json',
        },
      });

      const results = Array.isArray(response?.results) ? response.results : [];
      const paging = response?.paging || {};
      const parsedTotal = Number(paging.total);

      if (Number.isFinite(parsedTotal)) {
        total = parsedTotal;
      }

      if (!results.length) {
        break;
      }

      for (const order of results) {
        if (order?.id) {
          ordersById.set(String(order.id), order);
        }
      }

      offset += results.length;

      if (total !== null && offset >= total) {
        break;
      }
    }

    if (ordersById.size >= maxOrdersPerAccount) {
      break;
    }
  }

  return Array.from(ordersById.values()).slice(0, maxOrdersPerAccount);
}

function normalizeOrder(accountId, sellerId, order) {
  const statusDetail = order.status_detail || {};
  const shippingId = order.shipping?.id || order.shipping_id || null;
  const buyerId = order.buyer?.id || null;

  return {
    order_id: String(order.id),
    account_id: accountId,
    seller_id: Number(sellerId),
    buyer_id: buyerId === null || buyerId === undefined ? null : Number(buyerId),
    pack_id: order.pack_id === null || order.pack_id === undefined ? null : String(order.pack_id),
    shipping_id: shippingId === null || shippingId === undefined ? null : String(shippingId),
    status: order.status || null,
    status_detail_code: statusDetail.code || null,
    status_detail_description: statusDetail.description || null,
    currency_id: order.currency_id || null,
    total_amount: normalizeNumber(order.total_amount),
    paid_amount: normalizeNumber(order.paid_amount),
    fulfilled: order.fulfilled ?? null,
    buying_mode: order.buying_mode || null,
    tags: Array.isArray(order.tags) ? order.tags : [],
    date_created: normalizeDate(order.date_created),
    date_closed: normalizeDate(order.date_closed),
    expiration_date: normalizeDate(order.expiration_date),
    date_last_updated: normalizeDate(order.date_last_updated),
    raw: order,
    synced_at: nowIso(),
  };
}

function extractSellerSku(orderItem) {
  const variationAttributes = orderItem.item?.variation_attributes || [];
  const skuAttribute = variationAttributes.find((attribute) => {
    const id = String(attribute?.id || '').toUpperCase();
    const name = String(attribute?.name || '').toUpperCase();
