function buildDailySummaries(accountId, sellerId, orders, orderItems) {
  const summaries = new Map();

  for (const order of orders) {
    const snapshotDate = dateOnlyInTimeZone(order.date_created);
    const current = summaries.get(snapshotDate) || {
      account_id: accountId,
      seller_id: Number(sellerId),
      snapshot_date: snapshotDate,
      orders_count: 0,
      paid_orders_count: 0,
      canceled_orders_count: 0,
      units_sold: 0,
      gross_amount: 0,
      paid_amount: 0,
      avg_ticket: null,
      synced_at: nowIso(),
    };

    current.orders_count += 1;

    if (order.status === 'paid') {
      current.paid_orders_count += 1;
    }

    if (order.status === 'cancelled' || order.status === 'canceled') {
      current.canceled_orders_count += 1;
    }

    current.gross_amount += normalizeNumber(order.total_amount) || 0;
    current.paid_amount += normalizeNumber(order.paid_amount) || 0;
    summaries.set(snapshotDate, current);
  }

  for (const item of orderItems) {
    const order = orders.find((candidate) => String(candidate.id) === String(item.order_id));
    const snapshotDate = dateOnlyInTimeZone(order?.date_created);
    const current = summaries.get(snapshotDate);
    if (!current) continue;

    current.units_sold += normalizeInteger(item.quantity) || 0;
  }

  for (const summary of summaries.values()) {
    summary.avg_ticket = summary.orders_count > 0
      ? Number((summary.gross_amount / summary.orders_count).toFixed(2))
      : null;
  }

  return Array.from(summaries.values());
}

