    url: 'https://api.mercadolibre.com/oauth/token',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
      Accept: 'application/json',
    },
    body,
  });
}

async function getMercadoLivreSeller(accessToken) {
  return await request({
    method: 'GET',
    url: 'https://api.mercadolibre.com/users/me',
    headers: {
      Authorization: 'Bearer ' + accessToken,
      Accept: 'application/json',
    },
  });
}

async function fetchItemIds(accessToken, sellerId) {
  const itemIds = [];
  let offset = 0;
  let total = null;

  while (itemIds.length < maxItemsPerAccount) {
    const query = buildQuery({
      limit: itemPageLimit,
      offset,
    });

    const response = await request({
      method: 'GET',
      url: 'https://api.mercadolibre.com/users/' + encodeURIComponent(sellerId) + '/items/search?' + query,
      headers: {
        Authorization: 'Bearer ' + accessToken,
        Accept: 'application/json',
      },
    });

    const results = Array.isArray(response?.results) ? response.results : [];
    const paging = response?.paging || {};
    const parsedTotal = Number(paging.total);

    if (Number.isFinite(parsedTotal)) {
      total = parsedTotal;
    }

    if (!results.length) {
      break;
    }

    itemIds.push(...results);
    offset += results.length;

    if (total !== null && offset >= total) {
      break;
    }
  }

  return [...new Set(itemIds)].slice(0, maxItemsPerAccount);
}

async function fetchItemDetails(accessToken, itemIds) {
  const details = [];
  const errors = [];

  for (const chunk of chunkArray(itemIds, itemDetailBatchSize)) {
    const ids = chunk.map((itemId) => encodeURIComponent(itemId)).join(',');

    const response = await request({
      method: 'GET',
      url: 'https://api.mercadolibre.com/items?ids=' + ids,
      headers: {
        Authorization: 'Bearer ' + accessToken,
        Accept: 'application/json',
      },
    });

    const rows = Array.isArray(response) ? response : [];

    for (const row of rows) {
      if (row?.code >= 200 && row?.code < 300 && row?.body) {
        details.push(row.body);
      } else {
        errors.push({
          item_id: row?.body?.id || null,
          code: row?.code || null,
          body: row?.body || row,
        });
      }
    }
  }

  return { details, errors };
}

function normalizeNumber(value) {
  if (value === null || value === undefined || value === '') return null;
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}

function normalizeInteger(value) {
  const number = normalizeNumber(value);
  return number === null ? null : Math.trunc(number);
}

function normalizeItem(accountId, sellerId, item) {
  const shipping = item.shipping || {};

  return {
    item_id: item.id,
    account_id: accountId,
    seller_id: String(sellerId),
    title: item.title || null,
    category_id: item.category_id || null,
    status: item.status || null,
    price: normalizeNumber(item.price),
    base_price: normalizeNumber(item.base_price),
    original_price: normalizeNumber(item.original_price),
    available_quantity: normalizeInteger(item.available_quantity),
    sold_quantity: normalizeInteger(item.sold_quantity),
    listing_type_id: item.listing_type_id || null,
    condition: item.condition || null,
    catalog_listing: item.catalog_listing ?? null,
    free_shipping: shipping.free_shipping ?? null,
    logistic_type: shipping.logistic_type || null,
    permalink: item.permalink || null,
    thumbnail: item.thumbnail || null,
    last_updated: item.last_updated || null,
    raw: item,
    synced_at: nowIso(),
  };
}

function buildSnapshot(currentItem) {
  return {
    account_id: currentItem.account_id,
    seller_id: currentItem.seller_id,
    item_id: currentItem.item_id,
    snapshot_date: todayInTimeZone(),
    status: currentItem.status,
    price: currentItem.price,
    base_price: currentItem.base_price,
    original_price: currentItem.original_price,
    available_quantity: currentItem.available_quantity,
    sold_quantity: currentItem.sold_quantity,
    listing_type_id: currentItem.listing_type_id,
    free_shipping: currentItem.free_shipping,
    logistic_type: currentItem.logistic_type,
    raw: currentItem.raw,
    synced_at: currentItem.synced_at,
  };
}

async function upsertRows(table, rows, onConflict) {
  if (!rows.length) return [];

  const responses = [];

  for (const chunk of chunkArray(rows, supabaseUpsertBatchSize)) {
    const response = await supabaseRequest(
      'POST',
      '/' + table + '?on_conflict=' + encodeURIComponent(onConflict),
      chunk,
      'resolution=merge-duplicates,return=minimal'
    );

    responses.push(response);
  }

  return responses;
}

const accountsResponse = await supabaseRequest(
  'GET',
  '/oauth_tokens?select=account_id,refresh_token,access_token,expires_at,ml_user_id,accounts!inner(account_name,active)&accounts.active=eq.true'
);

let accounts = Array.isArray(accountsResponse) ? accountsResponse : [accountsResponse].filter(Boolean);

if (targetAccountId) {
  accounts = accounts.filter((account) => String(account.account_id) === targetAccountId);
}

if (targetSellerId) {
  accounts = accounts.filter((account) => String(account.ml_user_id || '') === targetSellerId);
}
const results = [];

if (!accounts.length) {
  return [
    {
      json: {
        status: 'success',
        message: 'Nenhuma conta ativa com refresh_token encontrada.',
        processed: 0,
      },
    },
  ];
}

for (const account of accounts) {
  let runId = null;
  const accountId = account.account_id;
  const accountName = account.accounts?.account_name || null;

  try {
    if (!accountId) throw new Error('Linha de oauth_tokens sem account_id.');
    if (!account.refresh_token) throw new Error('Conta ' + accountId + ' sem refresh_token.');

    runId = await createSyncRun(accountId);

    const accessToken = account.access_token || null;
    let sellerId = account.ml_user_id || null;
    const expiresAtTime = account.expires_at ? new Date(account.expires_at).getTime() : 0;
    const hasValidAccessToken = accessToken && expiresAtTime > Date.now() + 5 * 60 * 1000;

    if (!hasValidAccessToken) {
      throw new Error('Access token ausente ou vencido. Este fluxo renova token apenas no node MVP1 Seller; confirme que o MVP1 rodou antes deste node.');
    }

    if (!sellerId) {
      const seller = await getMercadoLivreSeller(accessToken);
      sellerId = seller?.id || null;
    }

    if (!sellerId) {
      throw new Error('Nao foi possivel identificar o seller_id da conta ' + accountId + '.');
    }

    const itemIds = await fetchItemIds(accessToken, sellerId);
    const { details, errors } = await fetchItemDetails(accessToken, itemIds);
    const currentItems = details
      .filter((item) => item?.id)
      .map((item) => normalizeItem(accountId, sellerId, item));

    await upsertRows('items_current', currentItems, 'item_id');

    if (syncDailySnapshot) {
      await upsertRows('item_daily_snapshots', currentItems.map(buildSnapshot), 'item_id,snapshot_date');
    }

    await supabaseRequest(
      'PATCH',
      '/accounts?id=eq.' + encodeURIComponent(accountId),
      {
        last_sync_at: nowIso(),
        updated_at: nowIso(),
      },
      'return=representation'
    );

    await finishSyncRun(runId, accountId, 'success');

    results.push({
      json: {
        status: 'success',
        account_id: accountId,
        account_name: accountName,
        seller_id: String(sellerId),
        item_ids_found: itemIds.length,
        items_synced: currentItems.length,
        item_detail_errors: errors.length,
        snapshot_date: todayInTimeZone(),
        sync_run_id: runId,
      },
    });
  } catch (error) {
    try {
      await finishSyncRun(runId, accountId, 'error', error);
    } catch (logError) {
      results.push({
        json: {
          status: 'error',
          account_id: accountId || null,
          account_name: accountName,
          error: compactError(error),
          log_error: compactError(logError),
        },
      });
      continue;
    }

    results.push({
      json: {
        status: 'error',
        account_id: accountId || null,
        account_name: accountName,
        error: compactError(error),
        sync_run_id: runId,
      },
    });
  }
}

return results;
